                  />
                  <Tooltip />
                  <Legend />
                  <Bar
                    dataKey="captureMt"
                    name="Capture"
                    stackId="a"
                    fill={COLORS.capture}
                  />
                  <Bar
                    dataKey="aquaMt"
                    name="Aquaculture"
                    stackId="a"
                    fill={COLORS.aqua}
                    radius={[4, 4, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Regime map"
            subtitle="Majority source of regional tonnage"
